import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec3, texture, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, PointLight, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const accentColor = new Color(colors.accent);

  const group = new Group();
  group.name = 'hub-collection-card-3-sprite';

  // atlas region aspect: 512x320
  const aspect = 512 / 320;
  const cardHeight = 1.4;
  const cardWidth = cardHeight * aspect;

  // ---- depth plane 1: contact shadow (grounding) ----
  const shadowRadiusX = cardWidth * 1.25;
  const shadowRadiusY = cardHeight * 0.5;
  const shadowGeo = new PlaneGeometry(shadowRadiusX, shadowRadiusY, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const suv = uv();
    const dist = suv.sub(0.5).mul(2.0).length();
    const alpha = smoothstep(1.0, 0.15, dist).mul(0.5);
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = alpha;
  }
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -cardHeight * 0.62, -0.08);
  group.add(shadowMesh);

  // ---- depth plane 2: accent border frame (<=10% of frame) ----
  const borderPad = 0.06;
  const borderGeo = new PlaneGeometry(cardWidth + borderPad, cardHeight + borderPad, 1, 1);
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b);
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.set(0, 0, -0.02);
  group.add(borderMesh);

  // ---- depth plane 3: card front — engineered gradient + grain ----
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight, 1, 1);
  const cardMat = new MeshBasicNodeMaterial();
  const gradTop = vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b);
  const gradBottom = vec3(inkColor.r, inkColor.g, inkColor.b);
  const cardUv = uv();
  const gradient = mix(gradBottom, gradTop, smoothstep(0.0, 1.0, cardUv.y));
  cardMat.colorNode = gradient;

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  group.add(cardMesh);

  // ---- local rim light (accent-tinted, node-local, <=1.5) ----
  const rimLight = new PointLight(accentColor, 0.9, 6, 2.0);
  rimLight.position.set(-cardWidth * 0.6, cardHeight * 0.4, 1.2);
  group.add(rimLight);

  // async grain texture load — blended into gradient once ready
  let loadedTexture = null;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      const grainNode = texture(tex);
      const grainLuma = grainNode.r.mul(0.6).add(0.4);
      cardMat.colorNode = gradient.mul(grainLuma);
      cardMat.needsUpdate = true;
    })
    .catch(() => {});

  // ---- idle motion: single slow breathing transform (<=2%) ----
  const tl = gsap.timeline({ repeat: -1, yoyo: true, defaults: { ease: 'sine.inOut' } });
  tl.to(group.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 4.2 });

  // entrance: weighted settle
  group.scale.setScalar(0.98);
  gsap.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(group.scale);

    shadowGeo.dispose();
    shadowMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();

    if (loadedTexture) {
      loadedTexture.dispose();
    }

    group.remove(rimLight);
    group.remove(shadowMesh);
    group.remove(borderMesh);
    group.remove(cardMesh);

    void texPromise;
  };

  return group;
}
